WITH RECURSIVE x9 AS (SELECT 1, CONCAT(SHA2(RAND(), 0), SHA2(RAND(), 0)) UNION ALL SELECT x6.v22994 + 1, CONCAT(SHA2(RAND(), 0), SHA2(RAND(), 0)) FROM x12 WHERE x6.v22994 < 10000) SELECT x6.v22994, x6.v22994, LEAD(x6.v22994, 0, x6.v22994) OVER () AS x3, x6.v22994 FROM v22993 AS x6 WHERE x6.v22994 <> 0.9